public interface ITopKProducts
{
    IReadOnlyList<(string ProductId, long Count)> GetTopK(int k);
    void RecordView(string productId);
}

public sealed class TopKProducts : ITopKProducts
{
    private readonly object _sync = new();
    private readonly Dictionary<string, long> _counts = new();

    public void RecordView(string productId)
    {
        lock (_sync)
        {
            _counts.TryGetValue(productId, out var c);
            _counts[productId] = c + 1;
        }
    }

    public IReadOnlyList<(string ProductId, long Count)> GetTopK(int k)
    {
        lock (_sync)
        {
            return _counts
                .OrderByDescending(kv => kv.Value)
                .ThenBy(kv => kv.Key, StringComparer.Ordinal)
                .Take(k)
                .Select(kv => (kv.Key, kv.Value))
                .ToList();
        }
    }
}
